statement:
The string `s` is a valid arithmetic expression built from single-digit numbers (`0` to `9`) joined by `+` and `*`, such as `"3+5*2"`. Its **correct value** follows the usual precedence: first every multiplication is carried out from left to right, then every addition from left to right.

Each entry of `answers` is one student's submitted result (in no particular order). Grade each answer and return the total of all grades:

- 5 points if it equals the correct value;
- otherwise 2 points if it equals a value the expression can produce when its operators are applied in some other order with correct arithmetic, that is, the value of some full parenthesization of `s`;
- otherwise 0 points.

validator:
function validate([s, answers]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 31 || s.length % 2 === 0) return 's must be an expression of 2 to 16 digits (length 3 to 31).';
  for (let i = 0; i < s.length; i++) {
    if (i % 2 === 0 ? !/[0-9]/.test(s[i]) : s[i] !== '+' && s[i] !== '*') return 's must alternate single digits with + or *.';
  }
  let sum = 0, term = Number(s[0]);
  for (let i = 1; i < s.length; i += 2) {
    if (s[i] === '*') { term *= Number(s[i + 1]); if (term > 1e9) return 'A product in the correct evaluation exceeds 10^9.'; }
    else { sum += term; term = Number(s[i + 1]); }
  }
  if (sum + term > 1000) return 'The correct value of s must be at most 1000.';
  if (!Array.isArray(answers) || answers.length < 1 || answers.length > 10000) return 'answers needs 1 to 10000 entries.';
  if (answers.some(a => !Number.isInteger(a) || a < 0 || a > 1000)) return 'Each answer is between 0 and 1000.';
  return null;
}

