function scoreOfStudents(s, answers) {
  // Correct value: split into terms at '+', multiply inside each term.
  const correct = s.split('+').reduce((sum, term) => sum + term.split('*').reduce((p, d) => p * Number(d), 1), 0);
  // Exact values of every full parenthesization, top-down by substring, never capped
  // (16 digits keep every value below 2^53).
  const memo = new Map();
  const all = (expr) => {
    if (memo.has(expr)) return memo.get(expr);
    const out = new Set();
    if (expr.length === 1) out.add(Number(expr));
    for (let k = 1; k < expr.length; k += 2) {
      for (const a of all(expr.slice(0, k))) for (const b of all(expr.slice(k + 1))) out.add(expr[k] === '+' ? a + b : a * b);
    }
    memo.set(expr, out);
    return out;
  };
  const values = all(s);
  let total = 0;
  for (const x of answers) total += x === correct ? 5 : values.has(x) ? 2 : 0;
  return total;
}

