function generate(rand, size) {
  const operands = size === 'large' ? 12 + Math.floor(rand() * 5) : 2 + Math.floor(rand() * 6);
  const evaluate = (digits, ops) => {
    let sum = 0, term = digits[0], peak = term;
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '*') { term *= digits[i + 1]; peak = Math.max(peak, term); }
      else { sum += term; term = digits[i + 1]; }
    }
    return [sum + term, peak];
  };
  let digits, ops, correct;
  for (;;) {
    const star = 0.2 + rand() * 0.5;
    digits = Array.from({ length: operands }, () => rand() < 0.15 ? 0 : Math.floor(rand() * (rand() < 0.5 ? 4 : 10)));
    ops = Array.from({ length: operands - 1 }, () => rand() < star ? '*' : '+');
    const [value, peak] = evaluate(digits, ops);
    if (value <= 1000 && peak <= 1e9) { correct = value; break; }
  }
  const s = digits.map((d, i) => d + (i < ops.length ? ops[i] : '')).join('');
  // All values of every parenthesization (capped at 1001), used to plant 2-point answers.
  const memo = new Map();
  const values = (l, r) => {
    const key = l * 32 + r;
    if (memo.has(key)) return memo.get(key);
    const out = new Set();
    if (l === r) out.add(digits[l]);
    for (let m = l; m < r; m++) for (const a of values(l, m)) for (const b of values(m + 1, r)) out.add(Math.min(ops[m] === '+' ? a + b : a * b, 1001));
    memo.set(key, out);
    return out;
  };
  const wrong = [...values(0, operands - 1)].filter(v => v <= 1000 && v !== correct);
  const count = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const answers = [];
  for (let i = 0; i < count; i++) {
    const pick = rand();
    if (pick < 0.3) answers.push(correct);
    else if (pick < 0.65 && wrong.length) answers.push(wrong[Math.floor(rand() * wrong.length)]);
    else answers.push(Math.floor(rand() * (size === 'large' ? 1001 : 30)));
  }
  return [s, answers];
}
